#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Maintain VERSION and README title; runtime header is generated by integration."""
import argparse,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]
a=argparse.ArgumentParser();a.add_argument('--set',dest='new');args=a.parse_args()
v=args.new if args.new is not None else (root/'VERSION').read_text().strip()
if not re.fullmatch(r'(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)',v):raise SystemExit('Expected major.minor.patch')
p=root/'README.md';text=p.read_text();title=f'# The Pony Desktop v{v}'
if args.new is not None:
    p.write_text(title+'\n'+text.split('\n',1)[1]);(root/'VERSION').write_text(v+'\n')
elif text.splitlines()[0]!=title:raise SystemExit('README title differs from VERSION')
print(v)
